  数据来源：万象拼音 dicts/zi.dict.yaml
            https://github.com/amzxyz/rime-wanxiang  (CC BY 4.0)
  原理：雾凇词库已通过 spelling_hints 在候选 comment 中给出「按词切分正确」
        的无调读音（例如输入 yin hang 时 comment 是 yin hang），本脚本用
        「候选汉字 + 无调音节」查万象单字表还原声调，因此多音字随词定调：
        银行 -> yín háng，音乐 -> yīn yuè，长大 -> zhǎng dà。
  开关：tone_hint_off（方案选单：带调标注 / 标注关，默认开启标注）
  关闭方式：删掉本文件与 rime_ice.custom.yaml，重新部署即可完全还原。
--]]
