local function utf8_chars(s)
  local t, i, n = {}, 1, #s
  while i <= n do
    local b = s:byte(i)
    local len = 1
    if b >= 0xF0 then len = 4
    elseif b >= 0xE0 then len = 3
    elseif b >= 0xC0 then len = 2 end
    if i + len - 1 > n then len = 1 end
    t[#t + 1] = s:sub(i, i + len - 1)
    i = i + len
  end
  return t
end

local function split_syllables(s)
  s = s:gsub("'", " ")
  local t = {}
  for w in s:gmatch("[^%s]+") do t[#t + 1] = w end
  return t
end

-- 返回带调拼音；无法对齐时返回 nil
local function tonelize(text, pinyin)
  local ss = split_syllables(pinyin)
  local cs = utf8_chars(text)
  if #ss == 0 or #ss ~= #cs then return nil end
  local out = {}
  for i = 1, #ss do
    local s = ss[i]
    if not s:match("^[a-z]+$") then return nil end
    local e = T[cs[i]]
    local v = e and e[s]
    out[i] = v or s      -- 生僻字/特殊音节查不到时，保留原来的无调读音
  end
  return table.concat(out, " ")
end

local function is_pinyin_comment(c)
  local p = c:match("^［(.-)］$")
  if p and #p > 0 then return p, true end
  if c:find("^[a-z]+[a-z ]*$") then return c, false end
  return nil, false
end

function M.init(env)
  local config = env.engine.schema.config
  M.style = config:get_string("tone_hint/style") or "{comment}"
  M.max_len = config:get_int("tone_hint/max_length") or 0
  M.keep_when_off = config:get_bool("tone_hint/keep_when_off") or false
end

function M.func(input, env)
  local on = not env.engine.context:get_option("tone_hint_off")
  for cand in input:iter() do
    local c = cand.comment or ""
    local py, bracketed = is_pinyin_comment(c)
    if py then
      if not on then
        if not M.keep_when_off then cand:get_genuine().comment = "" end
      elseif M.max_len <= 0 or #(utf8_chars(cand.text)) <= M.max_len then
        local t = tonelize(cand.text, py)
        if t then
          cand:get_genuine().comment = (M.style:gsub("{comment}", t))
        elseif bracketed then
          cand:get_genuine().comment = ""
        end
      end
    end
    yield(cand)
  end
end

return M
